  stage=make('main','ch-stage');const tools=make('header','ch-tools');title=make('span','ch-title');tools.append(title);const langButton=make('button','','FR / EN');langButton.setAttribute('aria-label','Changer de langue / Change language');langButton.onclick=()=>{language=language==='fr'?'en':'fr';location.search=language==='en'?'?lang=en':''};tools.append(langButton);
