 function closeCoheld(){if(!open)return;open=false;if(shell)shell.hidden=true;document.body.removeAttribute('data-coheld');document.documentElement.classList.remove('coheld-start');document.querySelectorAll('[data-code-on-screen-os]').forEach(e=>e.style.display='');document.querySelectorAll('[data-ch-hidden]').forEach(e=>{e.style.display='';e.removeAttribute('data-ch-hidden')});const t=document.getElementById('tab-coheld');t&&t.classList.remove('on')}
 function leave(id){closeCoheld();if(id==='tab-hx'){if(typeof window.showTab==='function')window.showTab('hx');return}const b=document.getElementById(id);b&&b.click();if(/^tab-insta/.test(id))setTimeout(()=>{typeof window.openFreshInsta==='function'&&window.openFreshInsta();addBtn()},0)}
